changeSet.sql:
ALTER TABLE integration.scoring_history RENAME TO plum_scoring;
ALTER TABLE integration.plum_scoring ADD COLUMN IF NOT EXISTS user_in TEXT;

UPDATE integration.plum_scoring s
   SET user_in = (SELECT COALESCE(u.pinfl, u.tin) FROM "user"."user" u WHERE u.id = s.user_id)
 WHERE s.user_id IS NOT NULL;

ALTER TABLE integration.plum_scoring DROP COLUMN IF EXISTS user_id;
